mapper.select:
SELECT m.id, m.household_id AS "householdId", m.lot_id AS "lotId", m.item_id AS "itemId", m.type, m.quantity, m.from_location_id AS "fromLocationId", m.to_location_id AS "toLocationId", m.reason, m.memo, m.operator_account_id AS "operatorAccountId", m.business_time AS "businessTime", m.created_at AS "createdAt", m.idempotency_key AS "idempotencyKey", m.reversal_of AS "reversalOf", i.name AS "itemName", u.name AS "unitName", fl.name AS "fromLocationName", tl.name AS "toLocationName", a.display_name AS "operatorDisplayName" FROM inventory_movement m JOIN catalog_item i ON i.id = m.item_id LEFT JOIN catalog_unit u ON u.id = i.unit_id LEFT JOIN location fl ON fl.id = m.from_location_id LEFT JOIN location tl ON tl.id = m.to_location_id LEFT JOIN account a ON a.id = m.operator_account_id
m.household_id = #{householdId} AND m.type = #{type} AND m.item_id = #{itemId} AND (m.from_location_id = #{locationId} OR m.to_location_id = #{locationId}) AND m.operator_account_id = #{operatorAccountId} AND m.business_time >= #{from} AND m.business_time < #{to}
ORDER BY ${orderBy}

SELECT id, lot_id, item_id, type, quantity, from_location_id, to_location_id,
       reason, operator_account_id, reversal_of, business_time, created_at
FROM inventory_movement
WHERE household_id = #{householdId}
  AND created_at > #{cursor}
ORDER BY created_at ASC
LIMIT #{limit}
